import{_ as t,o as r,c as a,a0 as o}from"./chunks/framework.CfecN1Ke.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"cypera","text":"Org docs, generated once","tagline":"Reusable crate-map, CLI-reference, and config-reference generation — the shared successor to the per-repo docs/gen-*.py scripts.","actions":[{"theme":"brand","text":"Get started","link":"/tutorials/getting-started"},{"theme":"alt","text":"Command reference","link":"/reference/commands"}]},"features":[{"title":"One generator, every repo","details":"The same three pages every sibling docs site needs — rendered by one tool instead of drifting per-repo Python scripts."},{"title":"Sources stay canonical","details":"Cargo.tomls, lib.rs module docs, gen-cli-docs output, and config-struct doc comments are the source of truth — pages are regenerated, never hand-edited."},{"title":"Pure core, thin shell","details":"cypera-core is string-in/markdown-out with no I/O; cypera-cli owns argv and filesystem walks."}]},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),n={name:"index.md"};function s(d,e,c,i,l,h){return r(),a("div",null,[...e[0]||(e[0]=[o('<h2 id="what-it-is" tabindex="-1">What it is <a class="header-anchor" href="#what-it-is" aria-label="Permalink to &quot;What it is&quot;">​</a></h2><p>Cypera is the org&#39;s reusable documentation generator: crate maps, CLI references, config references, rustdoc index pages, and the <code>cypera check</code> docs contract — rendered once for every sibling repo instead of per-repo <code>gen-*.py</code> scripts.</p><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to &quot;Why&quot;">​</a></h2><p>Every 9aia docs site regenerates the same pages from the same sources. Per-repo scripts drifted; cypera kills the drift — one generator, one <code>cypera.toml</code> contract per repo, generated-not- handwritten as an enforced rule.</p><h2 id="boundary" tabindex="-1">Boundary <a class="header-anchor" href="#boundary" aria-label="Permalink to &quot;Boundary&quot;">​</a></h2><ul><li><strong>Owns:</strong> reference-doc generation + the docs contract check.</li><li><strong>Doesn&#39;t own:</strong> the docs sites themselves, <code>gen-cli-docs</code> producers, rustdoc internals, or any engine&#39;s ledger/coordination.</li></ul><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><table tabindex="0"><thead><tr><th>You want to…</th><th>Go to</th></tr></thead><tbody><tr><td>Install and generate your first page</td><td><a href="/cypera/tutorials/getting-started.html">Tutorial</a></td></tr><tr><td>Do a task (crate map, CLI ref, config ref, docs check)</td><td><a href="/cypera/how-to/">How-to</a></td></tr><tr><td>Understand the design (core/shell split, markers, contract)</td><td><a href="/cypera/explanation/">Explanation</a></td></tr><tr><td>Look up a verb, option, or config field</td><td><a href="/cypera/reference/commands.html">Reference</a></td></tr></tbody></table>',8)])])}const f=t(n,[["render",s]]);export{g as __pageData,f as default};
